import {W,H,trace} from './rules.js';
const tankPhoto=new Image();tankPhoto.src=new URL('./assets/tank-photoreal.png',import.meta.url).href;tankPhoto.onload=()=>window.dispatchEvent(new Event('artillery-assets-loaded'));
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function line(c,points){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke();}
function sky(c){const bg=c.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#142536');bg.addColorStop(.48,'#566f7b');bg.addColorStop(.88,'#d0a986');bg.addColorStop(1,'#e3b48a');c.fillStyle=bg;c.fillRect(0,0,W,H);const sun=c.createRadialGradient(750,230,5,750,230,200);sun.addColorStop(0,'#f8d8a593');sun.addColorStop(1,'#f8d8a500');c.fillStyle=sun;c.fillRect(500,10,460,420);for(let layer=0;layer<3;layer++){c.fillStyle=['#84919255','#586d7366','#394f5866'][layer];c.beginPath();c.moveTo(0,390);for(let x=0;x<=W;x+=8)c.lineTo(x,330+layer*26+20*Math.sin(x/(60+layer*20)+layer*2)+10*Math.sin(x/27+layer));c.lineTo(W,H);c.lineTo(0,H);c.fill();}for(let i=0;i<6;i++){const x=(i*179+60)%W,y=80+(i%3)*31;c.fillStyle='#e4dfd41c';c.beginPath();c.ellipse(x,y,90,13,-.05,0,Math.PI*2);c.fill();}}
function ground(c,g){c.save();c.beginPath();c.moveTo(0,H);c.lineTo(0,g[0]);for(let x=1;x<W;x+=2)c.lineTo(x,g[x]);c.lineTo(W,H);c.closePath();c.clip();const dirt=c.createLinearGradient(0,310,0,H);dirt.addColorStop(0,'#6d7458');dirt.addColorStop(.25,'#5c5946');dirt.addColorStop(1,'#292f32');c.fillStyle=dirt;c.fillRect(0,0,W,H);for(let i=0;i<1200;i++){const x=(i*457.7)%W,y=315+(i*173.3)%(H-315),v=i%5;c.fillStyle=v===0?'#d4c39a30':v===1?'#1d24252b':'#7e817433';c.fillRect(x,y,1+v%3,1+v%2);}c.restore();c.strokeStyle='#a3a987';c.lineWidth=3;line(c,g.filter((_,x)=>x%3===0).map((y,i)=>[i*3,y]));for(let x=13;x<W;x+=21){const y=g[x];c.strokeStyle='#798b65aa';c.lineWidth=1;c.beginPath();c.moveTo(x,y);c.lineTo(x-2-(x%5),y-4-(x%3));c.moveTo(x,y);c.lineTo(x+2,y-3-(x%4));c.stroke();}}
function hull(c,p,index){c.save();c.translate(p.x,p.y);c.rotate(p.rotation||0);const base=index?'#8c6259':'#657667',light=index?'#b18a75':'#a0aa91',dark=index?'#423c3a':'#313b3a';c.fillStyle='#13202480';c.beginPath();c.ellipse(0,12,27,5,0,0,7);c.fill();c.fillStyle=dark;c.beginPath();c.roundRect(-24,-4,48,18,8);c.fill();for(let i=-2;i<=2;i++){c.fillStyle='#202726';c.beginPath();c.arc(i*10,6,6.5,0,7);c.fill();c.fillStyle='#85877b';c.beginPath();c.arc(i*10,6,3.4,0,7);c.fill();c.fillStyle='#343a37';c.beginPath();c.arc(i*10,6,1.5,0,7);c.fill();}const grad=c.createLinearGradient(0,-17,0,4);grad.addColorStop(0,light);grad.addColorStop(.55,base);grad.addColorStop(1,dark);c.fillStyle=grad;c.beginPath();c.moveTo(-22,-4);c.lineTo(-17,-14);c.lineTo(14,-14);c.lineTo(23,-6);c.lineTo(22,1);c.lineTo(-22,1);c.closePath();c.fill();c.strokeStyle='#d5d0b166';c.lineWidth=1;c.stroke();c.fillStyle='#242d2d';c.fillRect(-11,-12,8,4);c.fillRect(5,-12,7,3);c.fillStyle='#ddd2aa88';for(const x of [-16,-9,11,17])c.fillRect(x,-3,1,2);c.restore();}
function turret(c,p,index,dir){const base=index?'#8e6b5e':'#718474',light=index?'#cfab89':'#bbbea1';c.save();c.translate(p.x,p.y);c.rotate(p.rotation||0);const t=c.createLinearGradient(0,-28,0,-10);t.addColorStop(0,light);t.addColorStop(1,base);c.fillStyle=t;c.beginPath();c.moveTo(-12,-14);c.lineTo(-9,-24);c.lineTo(3,-28);c.lineTo(13,-23);c.lineTo(15,-14);c.closePath();c.fill();c.strokeStyle='#2c3736';c.lineWidth=1;c.stroke();c.fillStyle='#293535';c.fillRect(-3,-26,5,3);c.restore();const angle=p.angle*Math.PI/180,sx=p.x,sy=p.y-18,ex=sx+dir*34*Math.cos(angle),ey=sy-34*Math.sin(angle);c.strokeStyle='#1e2a2d';c.lineWidth=11;c.lineCap='round';line(c,[[sx,sy],[ex,ey]]);c.strokeStyle=light;c.lineWidth=7;line(c,[[sx,sy],[ex,ey]]);c.strokeStyle='#e4d1a4aa';c.lineWidth=1.5;line(c,[[sx,sy-2],[ex,ey-2]]);c.fillStyle='#2a302d';c.beginPath();c.arc(ex,ey,4.5,0,7);c.fill();c.fillStyle='#e7c498';c.beginPath();c.arc(ex,ey,2,0,7);c.fill();}
function tank(c,p,index,dir){c.save();c.fillStyle='#101d2299';c.beginPath();c.ellipse(p.x,p.y+15,39,5,0,0,7);c.fill();if(tankPhoto.complete&&tankPhoto.naturalWidth){c.translate(p.x,p.y);c.rotate(p.rotation||0);c.scale(dir,1);c.drawImage(tankPhoto,0,410,1536,614,-36,-16,72,40);c.restore();c.save();c.translate(p.x,p.y-17);c.scale(dir,1);c.rotate(-p.angle*Math.PI/180);c.drawImage(tankPhoto,300,45,1236,365,-17,-13,76,23);c.restore();c.fillStyle=index?'#e18e77':'#90d0b4';c.fillRect(p.x-5,p.y+17,10,3);}else{hull(c,p,index);turret(c,p,index,dir);c.restore();}}
function shell(c,x,y,a){c.save();c.translate(x,y);c.rotate(a);c.shadowColor='#ffd88b';c.shadowBlur=14;c.fillStyle='#d9b785';c.beginPath();c.moveTo(10,0);c.lineTo(2,-3.5);c.lineTo(-9,-3.2);c.lineTo(-9,3.2);c.lineTo(2,3.5);c.closePath();c.fill();c.fillStyle='#6b4934';c.fillRect(-9,-3.2,3,6.4);c.strokeStyle='#fff0c7';c.lineWidth=1;c.beginPath();c.moveTo(0,-2);c.lineTo(7,-.4);c.stroke();c.restore();}
function explosion(c,x,y,step,radius){const k=clamp(step/18,0,1);for(let i=0;i<20;i++){const a=i*2.399,r=(i%5+1)*radius*.15*k,px=x+Math.cos(a)*r,py=y+Math.sin(a)*r-11*k;c.fillStyle=i%3?'#342f2b80':'#d28f5d99';c.beginPath();c.arc(px,py,4+(i%4)*3+step*.28,0,7);c.fill();}const glow=c.createRadialGradient(x,y,2,x,y,radius*k);glow.addColorStop(0,'#fff0bb');glow.addColorStop(.3,'#ffbf66dd');glow.addColorStop(1,'#ff8c2c00');c.fillStyle=glow;c.beginPath();c.arc(x,y,radius*k,0,7);c.fill();}
export function render(c,game,{animation=null,preview=null}={}){sky(c);if(!game){c.fillStyle='#f0f0e4';c.textAlign='center';c.font='bold 42px system-ui';c.fillText('Klar til kamp?',W/2,235);c.font='20px system-ui';c.fillText('Vælg modstander for at begynde',W/2,275);return;}const flight=animation&&animation.index<animation.path.length,groundData=flight?animation.groundBefore:game.ground;ground(c,groundData);for(let i=0;i<2;i++){const base=game.players[i],motion=animation&&!flight&&animation.motion.length?animation.motion[Math.min(animation.motionIndex,animation.motion.length-1)]?.[i]:null,position=flight?animation.before[i]:motion||base;tank(c,{...base,...position},i,Math.sign(game.players[1-i].x-position.x)||1);}if(animation){const {path,index,hit}=animation;if(flight){c.strokeStyle='#ffe1a47a';c.lineWidth=2;c.setLineDash([5,5]);line(c,path.slice(Math.max(0,index-20),index).map(p=>p.slice(0,2)));c.setLineDash([]);const [x,y,a]=path[Math.min(index,path.length-1)];shell(c,x,y,a);}else explosion(c,hit.x,hit.y,index-path.length,animation.radius);}else if(preview){const t=trace(game,game.turn,preview.angle,preview.power);c.strokeStyle='#d5e4d388';c.lineWidth=1.6;c.setLineDash([2,9]);line(c,t.path.map(p=>p.slice(0,2)));c.setLineDash([]);}}
